import { RedwoodClient, canonicalize } from '@redwood/sdk'
const ckey = RedwoodClient.fingerprint({operation: 'create_invoice', payload})
const res = await client.request('/v1/invoices', {method: 'POST', headers: {'RWD-ID': ckey}})

// streaming
